import { useEffect, useRef, useState } from 'react';
import { Menu as MenuIcon, X } from 'lucide-react';
import About from './components/About';

// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-white", "surface": "bg-stone-50", "surface_2": "bg-stone-100", "heading_text": "text-stone-900", "body_text": "text-stone-600", "muted_text": "text-stone-500", "primary": "bg-stone-900", "primary_hover": "hover:bg-stone-700", "on_primary": "text-white", "border": "border-stone-200", "accent_text": "text-orange-600", "accent_bg": "bg-orange-50", "gradient": "from-stone-900 to-stone-600"};
const RADIUS = "rounded-xl";
const GRAD = "bg-gradient-to-br from-stone-900 to-stone-600";
const FONT_CSS = ".font-display{font-family: 'Space Grotesk', system-ui, sans-serif;} .font-body{font-family: 'Inter', system-ui, sans-serif;} body{font-family: 'Inter', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div ref={ref} className={`reveal ${visible ? 'reveal-visible' : ''}`}>{children}</div>
  );
}

