            <img src="" alt="NeedYou" className="h-7 w-auto" />
          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>N</span>
          )}
          <span className="font-display font-bold">NeedYou</span>
        </div>
        &copy; 2026 NeedYou. All rights reserved.
      </footer>
    </div>    );
}

