export default function About() {
  const [isContactOpen, setIsContactOpen] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });

  const handleFormChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Simulate a submission
    setTimeout(() => {
      setIsContactOpen(false);
      alert('Message sent! Thanks for reaching out.');
    }, 1200);
  };

  return (
    <div className="w-full min-h-[800px] bg-stone-900 text-stone-600 font-sans antialiased">
      {/* Decorative gradient header */}
      <div className="w-full h-48 bg-gradient-to-br from-stone-700 to-stone-800 to-transparent relative z-0" />

      {/* Card grid for skills & experience */}
