          {skills.map((skill) => (
            <div 
              key={skill.id}
              className="py-3 px-4 rounded-xl bg-stone-100 border border-stone-200 flex items-center gap-2 shadow-lg transition-all duration-300 hover:scale-[1.02] hover:shadow-stone-500/10"
            >
              <div className="w-5 h-5 text-orange-400 flex-shrink-0"><skill.icon size={16} /></div>
              <div className="text-sm font-medium text-stone-600">{skill.name}</div>
              <span className="inline-flex items-center justify-center w-12 h-6 text-[10px] font-semibold text-stone-600 bg-stone-500/20 rounded-full ml-auto">{skill.level}</span>
            </div>
          ))}
        </div>

        {/* Experience timeline */}
        <div className="space-y-6">
          {experiences.map((exp) => (
            <div key={exp.id} className="p-6 rounded-2xl bg-stone-100 border border-stone-200 shadow-lg transition-all duration-300 hover:scale-[1.01] hover:shadow-stone-500/10">
              <div className="flex items-start justify-between pb-4 border-b border-stone-200 mb-4">
                <div className="flex items-center space-x-2">
                  <div className="p-2 rounded-xl bg-stone-500/20 text-orange-400"><MapPin size={16} /></div>
                  <div>
                    <h3 className="font-bold text-stone-600">{exp.company}</h3>
                    <p className="text-stone-600 text-sm">{exp.title}</p>
                  </div>
                </div>
                <div className="flex flex-col items-end space-y-1">
                  <p className="text-stone-600 text-sm tracking-wider">{exp.period}</p>
                  <span className="inline-flex items-center gap-1 text-sm text-orange-400 bg-stone-500/20 px-2 rounded-full">
                    <Sparkles size={12} /> {exp.id}
                  </span>
                </div>
              </div>
              <div>
                <p className="text-stone-600 text-sm mb-4">{exp.role}</p>
                {exp.highlights.map((h, i) => (
                  <p key={i} className="text-stone-600 text-sm flex items-start gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500/20"></div>
                    {h}
                  </p>
                ))}
              </div>
            </div>
          ))}
        </div>
