      {/* Contact CTA */}
      <div className="max-w-7xl mx-auto p-6 sm:p-10 bg-stone-900/80 backdrop-blur-xl rounded-2xl border border-stone-200 mt-20">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6 mb-10">
          <div>
            <h3 className="text-xl font-bold text-stone-600">Get in Touch</h3>
            <p className="text-stone-600 text-sm mt-2">Ready to build something amazing?</p>
          </div>
          <button
            onClick={() => setIsContactOpen(true)}
            className="inline-flex items-center gap-2 py-3 px-6 rounded-xl bg-stone-600/10 border border-stone-500/20 hover:bg-stone-600/20 text-stone-600 font-semibold transition-all duration-300 active:scale-[0.98] active:shadow-none"
          >
            <Mail size={18} /> Connect
          </button>
        </div>

        {/* Contact Form Modal */}
        {isContactOpen && (
          <form onSubmit={handleSubmit} className="space-y-4 sm:w-[400px]">
            <div className="grid grid-cols-1 sm:grid-cols-2 sm:gap-4">
              <div className="relative z-10">
                <label htmlFor="name" className="block text-stone-600 text-sm mb-2">Full Name</label>
                <input 
                  type="text" 
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleFormChange}
                  className="w-full py-2 pl-6 pr-12 bg-stone-900/30 border border-stone-700 rounded-xl text-stone-600 focus:ring-2 focus:ring-stone-500/50 outline-none transition-all"
                  placeholder="Amey Chikane"
                  required
                />
                <div className="absolute right-3 top-2.5 p-1 rounded-xl bg-stone-100 text-stone-600"><UserCheck size={14} /></div>
              </div>

              <div className="relative z-10">
                <label htmlFor="email" className="block text-stone-600 text-sm mb-2">Email Address</label>
                <input 
                  type="email" 
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleFormChange}
                  className="w-full py-2 pl-6 pr-12 bg-stone-900/30 border border-stone-700 rounded-xl text-stone-600 focus:ring-2 focus:ring-stone-500/50 outline-none transition-all"
                  placeholder="ameychikane@scale.ai"
                  required
                />
                <div className="absolute right-3 top-2.5 p-1 rounded-xl bg-stone-100 text-stone-600"><Mail size={14} /></div>
              </div>
            </div>

            <textarea 
              name="message"
              value={formData.message}
              onChange={handleFormChange}
              className="w-full py-4 px-6 bg-stone-900/30 border border-stone-700 rounded-xl text-stone-600 focus:ring-2 focus:ring-stone-500/50 outline-none resize-y min-h-[100px] max-h-[300px] text-sm font-sans"
              placeholder="Briefly describe your project..."
              required
            ></textarea>

            <button 
              type="submit"
              className="w-full py-3 rounded-xl bg-stone-600/10 border border-stone-500/20 hover:bg-stone-600/20 text-stone-600 font-semibold transition-all duration-300 active:scale-[0.98] active:shadow-none"
            >
              <span className="inline-flex items-center gap-2">
                <Sparkles size={18} /> Send Message
              </span>
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

.font-display { font-family: 'Space Grotesk', system-ui, sans-serif; }
.font-body { font-family: 'Inter', system-ui, sans-serif; }
body { font-family: 'Inter', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

